examples.template:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
    MonarchAiArtifactVersions(selection: $version, versions: versions)
    Text(versions.first { $0.version == version }?.content ?? "")
}

examples.setupTemplate:
@State private var version = {{value}}
private let versions = [
    MonarchAiArtifactVersion({{versions.0.version}}, createdAt: {{versions.0.createdAt|date}}, content: {{versions.0.text}}),
    MonarchAiArtifactVersion({{versions.1.version}}, createdAt: {{versions.1.createdAt|date}}, label: {{versions.1.label}}, content: {{versions.1.text}}),
    MonarchAiArtifactVersion({{versions.2.version}}, createdAt: {{versions.2.createdAt|date}}, label: {{versions.2.label}}, content: {{versions.2.text}}),
]

examples.setup:
@State private var version = 3
private let versions = [
    MonarchAiArtifactVersion(1, createdAt: Date(timeIntervalSince1970: 1_773_306_000), content: "The team shipped the new onboarding flow in May. Sign-ups grew and support tickets went down."),
    MonarchAiArtifactVersion(2, createdAt: Date(timeIntervalSince1970: 1_773_307_200), label: "Shorter intro", content: "The team shipped the onboarding flow in May. Sign-ups grew by a fifth."),
    MonarchAiArtifactVersion(3, createdAt: Date(timeIntervalSince1970: 1_773_309_900), label: "Added risks", content: "The team shipped the onboarding flow in May. Sign-ups grew by a fifth. The main risk is the June migration."),
]

examples.code:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
    MonarchAiArtifactVersions(selection: $version, versions: versions)
    Text(versions.first { $0.version == version }?.content ?? "")
}

MonarchAiArtifactVersions(
    selection: $version,
    versions: (1...3).map {
        MonarchAiArtifactVersion($0, createdAt: Date(timeIntervalSinceReferenceDate: 800_000_000))
    },
    showsCompare: false
)
